def processRequests(n, restrictions, requests):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    out = []
    for u, v in requests:
        ru, rv = find(u), find(v)
        if ru == rv:
            out.append(1)
            continue
        ok = True
        for x, y in restrictions:
            fx, fy = find(x), find(y)
            if (fx == ru and fy == rv) or (fx == rv and fy == ru):
                ok = False
                break
        if ok:
            parent[ru] = rv
        out.append(1 if ok else 0)
    return out
